import functools
import time

def retry(func):
    """
    A decorator that retries a function up to 3 times if an exception is raised.

    Args:
        func (callable): The function to be decorated.

    Returns:
        callable: The wrapped function with retry logic.
    """
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        max_retries = 3
        last_exception = None

        for attempt in range(1, max_retries + 1):
            try:
                return func(*args, **kwargs)
            except Exception as e:
                last_exception = e
                print(f"Attempt {attempt} failed: {e}")

                if attempt < max_retries:
                    print("Retrying...")
                    # Small delay to prevent rapid-fire failure
                    time.sleep(0.5)
                else:
                    print("All retry attempts exhausted.")

        # If all attempts fail, raise the last caught exception
        if last_exception:
            raise last_exception

    return wrapper

# --- Demonstration Code ---

if __name__ == "__main__":
    # Counter to track how many times the function has been called
    call_count = 0

    @retry
    def unstable_function():
        """A function that fails the first two times and succeeds on the third."""
        global call_count
        call_count += 1

        print(f"Executing unstable_function (Call #{call_count})")

        if call_count < 3:
            raise ValueError("Temporary failure!")

        return "Success!"

    @retry
    def failing_function():
